function out = runSimulation(varargin)
%RUNSIMULATION Focused-excitation ISM membrane diffusion and tracking.
%
%   This file is the readable orchestration layer. Numerical details
%   are implemented by the neighboring package functions.

    projectDirectory = fileparts(fileparts(fileparts( ...
        mfilename('fullpath'))));
    addpath(projectDirectory);
    import membrane_tracking.focused_ism.*

    opts = parseInputs(varargin{:});
    if ~isempty(opts.rngSeed)
        rng(opts.rngSeed);
    end

    detector = makeDetector(opts);
    % Each emitter contributes x, y, and flux parameters, plus one shared
    % background parameter. Do not ask a channel vector to identify more
    % parameters than it contains.
    maxIdentifiableEmitters = floor((detector.nChannels - 1) / 3);
    opts.requestedMaxEmittersPerFitRegion = ...
        opts.maxEmittersPerFitRegion;
    opts.maxEmittersPerFitRegion = min( ...
        opts.maxEmittersPerFitRegion, maxIdentifiableEmitters);
    trajectories = simulateTrajectories(opts);
    [frames, photonEvents, photophysics] = simulatePhotonMovie( ...
        trajectories.positionsUm, detector, opts);

    localizationTable = localizeMovie(frames, detector, opts, ...
        trajectories.positionsUm, photophysics.detectedPhotonCountsInFov);
    [trackTable, diffusion, opts] = refineTrackingAndDiffusion( ...
        localizationTable, opts);
    diffusion.truthValidation = estimateTruthDiffusionDiagnostics( ...
        trajectories, trackTable, photophysics, opts);
    densityDiagnostics = summarizeDensityDiagnostics(localizationTable, ...
        trackTable, detector, diffusion, opts);
    experimentalBnp = emptyExperimentalBnpResult(opts);
    if opts.runExperimentalBnpSampler
        experimentalBnp = runExperimentalBnpSampler(frames, detector, ...
            trackTable, photophysics, diffusion, opts);
    end

    figureSummary = [];
    bnpCountFigure = [];
    if opts.makeFigure
        figureSummary = plotSummary(trajectories, frames, detector, ...
            localizationTable, trackTable, diffusion, experimentalBnp, opts);
        if experimentalBnp.countEstimateAvailable
            bnpCountFigure = plotBnpCountPosterior( ...
                experimentalBnp, photophysics, opts);
        end
    end

    if opts.writeOutputs || opts.saveFigures
        ensureDir(opts.outputDir);
        if opts.writeOutputs
            writeOutputs(opts.outputDir, opts, detector, trajectories, ...
                photonEvents, photophysics, localizationTable, trackTable, ...
                diffusion, densityDiagnostics, experimentalBnp, frames);
        end
        if opts.saveFigures && ~isempty(figureSummary)
            safeExportFigure(figureSummary, fullfile(opts.outputDir, ...
                'membrane_diffusion_tracking_summary.png'), 180);
        end
        if opts.saveFigures && ~isempty(bnpCountFigure)
            safeExportFigure(bnpCountFigure, fullfile(opts.outputDir, ...
                'brightness_constrained_count_posterior.png'), 180);
        end
    end

    if opts.verbose
        fprintf(['[focused ISM membrane SPT] true D = %.4g um^2/s, ' ...
            'lag-1 Fisher-corrected D = %.4g um^2/s, MSD-slope D = %.4g um^2/s, ' ...
            'step-likelihood D = %.4g um^2/s, ' ...
            '%d localizations, %d tracks, concentration %.3g um^-2, ' ...
            'rejected observations %.1f%%.\n'], ...
            opts.diffusionUm2PerS, diffusion.DLag1CorrectedUm2PerS, ...
            diffusion.DMsdCorrectedUm2PerS, diffusion.DFisherMLEUm2PerS, ...
            height(localizationTable), diffusion.nTracksUsed, ...
            opts.actualMoleculeConcentrationPerUm2, ...
            100 * diffusion.fractionRejectedForDiffusion);
        validation = diffusion.truthValidation;
        fprintf(['[diffusion audit] all-trajectory truth %.4g, ' ...
            'focus-detectable truth %.4g, accepted-track truth %.4g, ' ...
            'identity switches %.2f%%, localization variance/Fisher %.3g.\n'], ...
            validation.fullTrajectoryLag1DiffusionUm2PerS, ...
            validation.focusDetectableTruthLag1DiffusionUm2PerS, ...
            validation.acceptedTrackTruthLag1DiffusionUm2PerS, ...
            100 * validation.truthIdentitySwitchFraction, ...
            validation.localizationVarianceInflationOverFisher);
        fprintf(['[selection audit] hard-gate acceptance %.3f, ' ...
            'non-identifiable positions %.1f%%, tracking refinements %d, ' ...
            'final prior %.4g um^2/s.\n'], ...
            diffusion.meanHardGateAcceptanceProbability, ...
            100 * diffusion.fractionNonidentifiablePositions, ...
            diffusion.nTrackingRefinementIterations, ...
            opts.trackingPriorDiffusionUm2PerS);
        if experimentalBnp.wasRun
            if experimentalBnp.estimateAvailable
                fprintf(['[experimental joint sampler] posterior D %.4g, ' ...
                    '95%% interval [%.4g %.4g], ESS %.1f, split-Rhat %.3f, ' ...
                    'checks=%d, validated=%d (%s).\n'], ...
                    experimentalBnp.posteriorMeanD, ...
                    experimentalBnp.credibleIntervalD(1), ...
                    experimentalBnp.credibleIntervalD(2), ...
                    experimentalBnp.effectiveSampleSizeD, ...
                    experimentalBnp.splitRhatD, ...
                    experimentalBnp.passedApplicabilityChecks, ...
                    experimentalBnp.isValidatedForUse, ...
                    experimentalBnp.status);
                fprintf(['[brightness-constrained count] mode=%s, ' ...
                    'mean in focus %.3g, MAP total %d (P=%.3f), ' ...
                    'median frame decision %.3f, adjacent-count ' ...
                    'separation %.2f sigma, count checks=%d.\n'], ...
                    experimentalBnp.brightnessMode, ...
                    experimentalBnp.posteriorMeanEmittersInFocus, ...
                    experimentalBnp.posteriorMapActiveEmitterCount, ...
                    experimentalBnp.activeEmitterCountDecisionProbability, ...
                    experimentalBnp.medianFrameCountDecisionProbability, ...
                    experimentalBnp.adjacentCountSeparationSigma, ...
                    experimentalBnp.countDiagnosticsPassed);
            else
                fprintf('[experimental joint sampler] no estimate (%s).\n', ...
                    experimentalBnp.status);
            end
        end
    end

    out = struct();
    out.options = opts;
    out.detector = detector;
    out.trajectories = trajectories;
    out.frames = frames;
    out.photonEvents = photonEvents;
    out.photophysics = photophysics;
    out.localizationTable = localizationTable;
    out.trackTable = trackTable;
    out.diffusion = diffusion;
    out.densityDiagnostics = densityDiagnostics;
    out.experimentalBnp = experimentalBnp;
    out.figureSummary = figureSummary;
    out.bnpCountFigure = bnpCountFigure;
end
